css:
/* General Reset */
.container * {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  font-family: "Arial", sans-serif;
}

/* Container */
.container {
  --color1: #734652;
  --color2: #d98baf;
  --color3: #bf567d;
  width: 100%;
  height: 100%;
  background: radial-gradient(
      circle at top left,
      var(--color1),
      transparent 40%
    ),
    radial-gradient(circle at bottom right, var(--color2), transparent 40%),
    linear-gradient(
      45deg,
      var(--color3) 25%,
      transparent 25%,
      transparent 75%,
      var(--color3) 75%,
      var(--color3)
    );
  background-size:
    120px 120px,
    150px 150px,
    90px 90px;
  background-position:
    0 0,
    100% 100%,
    0 0;
  position: relative;
  margin: 50px auto;
  padding: 2rem;
  border-radius: 3rem;
  box-shadow: 0 10px 20px rgba(0, 0, 0, 0.3);
  overflow: hidden;
}

.container:before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: repeating-linear-gradient(
    45deg,
    rgba(255, 255, 255, 0.2) 10px,
    transparent 10px,
    transparent 20px
  );
  opacity: 0.4;
  z-index: 0;
}

.container * {
  position: relative;
  z-index: 1;
}
